<script setup>
import {ref,onMounted,onBeforeUnmount,computed,nextTick} from 'vue'
import {ElMessage} from 'element-plus'
import {MathUtils} from 'three'
import {createStudio,assetModel,categories,modelDB,dbCall} from './studio'
import {EQUIPMENT_ASSETS} from './equipment'
import PlanCanvas from './PlanCanvas.vue'
const aiEnabled = import.meta.env.VITE_AI_ENABLED !== 'false'
const aiDisabledMessage = '服务器展示版未启用 AI 生成，设备导入与布置可正常使用'
const planning=ref(false),search=ref('')
const equipmentIcons={stacker:'Ⅱ',rack:'▦',shuttle:'▣',conveyor:'≋',sorter:'⇄',pallet:'▤',robot:'◉',lift:'↕',station:'▣',dock:'⇆',safety:'△',sensor:'⌖',other:'◇'}
async function generate3D(){planning.value=false;await nextTick();studio?.frameAll()}
function movePlan(p){const previous=placements.value.find(x=>x.id===p.id);if(previous)studio.update(p.id,{position:[p.x,previous.position[1],p.z]})}
async function dropPlan(p){const asset=assets.value.find(a=>a.id===p.assetId);if(!asset)return;try{await studio.add(asset,{position:[p.x,0,p.z]})}catch(e){ElMessage.error('平面放置失败：'+e.message)}}
const emit=defineEmits(['close'])
const host=ref(),aiPreviewHost=ref(),fileInput=ref(),category=ref('stacker'),filter=ref('all'),units=ref('auto'),busy=ref(false),selection=ref(null),placements=ref([]),mode=ref('translate'),snap=ref(true),ready=ref(false)
const assets=ref(EQUIPMENT_ASSETS.map(a=>({...a})))
const aiOpen=ref(false),aiType=ref('2d'),aiPrompt=ref(''),aiFeedback=ref(''),aiBusy=ref(false),aiProgress=ref(''),aiReady=ref({openai:false,meshy:false,anthropic:false}),generatedSvg=ref(''),generatedAsset=ref(null),generatedPrompt=ref(''),aiSettingsOpen=ref(false),svgProvider=ref('anthropic'),openAiToken=ref(''),anthropicToken=ref(''),anthropicBaseUrl=ref('https://api.apikey.fun'),anthropicModel=ref('claude-sonnet-4-5'),meshyToken=ref(''),openAiModel=ref('gpt-4.1-mini'),meshyModel=ref('meshy-t2.5'),serverAiReady=ref({openai:false,meshy:false,anthropic:false})
const filtered=computed(()=>assets.value.filter(a=>(filter.value==='all'||a.category===filter.value)&&((a.name+' '+(a.description||'')+' '+(a.spec||'')).toLowerCase().includes(search.value.toLowerCase()))))
let studio,aiPreviewStudio,db,restoring=true,alive=true
const label=id=>categories.find(c=>c[0]===id)?.[1]||'其他设备'
function saveLayout(list){placements.value=list;if(!restoring)try{localStorage.setItem('warehouse-studio-layout-v1',JSON.stringify(list))}catch{ElMessage.warning('布局本地保存失败，请导出布局备份')}}
async function place(asset,drop){try{const result=await studio.add(asset,{},drop);if(result&&!planning.value)studio.focus(result.id)}catch(e){ElMessage.error('模型加载失败：'+e.message)}}
function drag(asset,event){event.dataTransfer.setData('application/warehouse-asset',asset.id);event.dataTransfer.effectAllowed='copy'}
function drop(event){const asset=assets.value.find(a=>a.id===event.dataTransfer.getData('application/warehouse-asset'));if(asset)place(asset,{x:event.clientX,y:event.clientY})}
async function importModel(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;const ext=file.name.split('.').pop().toLowerCase();if(!['glb','gltf','stl','obj'].includes(ext)){ElMessage.warning('SolidWorks 原生 SLDPRT / SLDASM / STEP 请先转换为 GLB、STL 或 OBJ');return}if(file.size>30*1024*1024){ElMessage.warning('单模型限制 30 MB，请先简化网格');return}busy.value=true
 try{const buffer=await file.arrayBuffer();if(ext==='gltf'){const data=JSON.parse(new TextDecoder().decode(buffer));if([...(data.buffers||[]),...(data.images||[])].some(x=>x.uri&&!x.uri.startsWith('data:')))throw Error('请打包为 GLB，或使用内嵌资源的 glTF；不支持外部纹理/二进制文件')}
 const asset={id:MathUtils.generateUUID(),name:file.name,category:category.value,units:units.value==='auto'?(ext==='glb'||ext==='gltf'?'m':'mm'):units.value,ext,buffer};const preview=await assetModel(asset);preview.traverse(o=>{o.geometry?.dispose();const mats=Array.isArray(o.material)?o.material:[o.material];mats.forEach(m=>{if(m){Object.values(m).filter(v=>v?.isTexture).forEach(t=>t.dispose());m.dispose()}})});if(!alive)return
 if(db)await dbCall(db,'put',asset);assets.value.push(asset);filter.value=asset.category;ElMessage.success(db?'模型已按设备分类保存，拖入画布即可布置':'模型已加载到本次会话，本地存储不可用')
 }catch(e){ElMessage.error('导入失败：'+e.message)}finally{busy.value=false}}
function aiHeaders(){return {'x-openai-api-key':openAiToken.value,'x-anthropic-api-key':anthropicToken.value,'x-meshy-api-key':meshyToken.value}}
function loadAiSettings(){if(!aiEnabled)return;try{openAiToken.value=sessionStorage.getItem('warehouse-ai-openai-token')||'';anthropicToken.value=sessionStorage.getItem('warehouse-ai-anthropic-token')||'';anthropicBaseUrl.value=sessionStorage.getItem('warehouse-ai-anthropic-base-url')||'https://api.apikey.fun';anthropicModel.value=sessionStorage.getItem('warehouse-ai-anthropic-model')||'claude-sonnet-4-5';svgProvider.value=sessionStorage.getItem('warehouse-ai-svg-provider')||'anthropic';meshyToken.value=sessionStorage.getItem('warehouse-ai-meshy-token')||'';openAiModel.value=sessionStorage.getItem('warehouse-ai-openai-model')||'gpt-4.1-mini';meshyModel.value=sessionStorage.getItem('warehouse-ai-meshy-model')||'meshy-t2.5'}catch{}}
async function refreshAiStatus(){if(!aiEnabled)return;try{const r=await fetch('/api/ai/status',{headers:aiHeaders()});if(r.ok){serverAiReady.value=await r.json();aiReady.value={openai:serverAiReady.value.openai||!!openAiToken.value,anthropic:serverAiReady.value.anthropic||!!anthropicToken.value,meshy:serverAiReady.value.meshy||!!meshyToken.value}}}catch{aiReady.value={openai:!!openAiToken.value,anthropic:!!anthropicToken.value,meshy:!!meshyToken.value}}}
async function saveAiSettings(){if(!aiEnabled)return;try{openAiToken.value?sessionStorage.setItem('warehouse-ai-openai-token',openAiToken.value):sessionStorage.removeItem('warehouse-ai-openai-token');anthropicToken.value?sessionStorage.setItem('warehouse-ai-anthropic-token',anthropicToken.value):sessionStorage.removeItem('warehouse-ai-anthropic-token');sessionStorage.setItem('warehouse-ai-anthropic-base-url',anthropicBaseUrl.value.trim().replace(/\/+$/,''));sessionStorage.setItem('warehouse-ai-anthropic-model',anthropicModel.value.trim());sessionStorage.setItem('warehouse-ai-svg-provider',svgProvider.value);meshyToken.value?sessionStorage.setItem('warehouse-ai-meshy-token',meshyToken.value):sessionStorage.removeItem('warehouse-ai-meshy-token');sessionStorage.setItem('warehouse-ai-openai-model',openAiModel.value);sessionStorage.setItem('warehouse-ai-meshy-model',meshyModel.value);aiSettingsOpen.value=false;await refreshAiStatus();ElMessage.success('配置已保存在当前浏览器会话，关闭标签页后需重新配置')}catch{ElMessage.error('浏览器会话存储不可用，请检查浏览器设置')}}
function clearAiSettings(){openAiToken.value='';anthropicToken.value='';meshyToken.value='';try{for(const key of ['warehouse-ai-openai-token','warehouse-ai-anthropic-token','warehouse-ai-anthropic-base-url','warehouse-ai-anthropic-model','warehouse-ai-svg-provider','warehouse-ai-meshy-token'])sessionStorage.removeItem(key)}catch{}refreshAiStatus();ElMessage.success('已清除当前浏览器会话中的 Token')}
function svgPreviewUrl(svg){return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`}
async function apiJson(url,options={}){if(!aiEnabled)throw Error(aiDisabledMessage);const r=await fetch(url,{...options,headers:{...aiHeaders(),...options.headers}});const data=r.headers.get('content-type')?.includes('application/json')?await r.json():null;if(!r.ok)throw Error(data?.error||`请求失败 (${r.status})`);return data}
async function waitMeshy(id,label){for(let i=0;i<100;i++){if(!alive)throw Error('页面已关闭');const task=await apiJson(`/api/ai/3d/tasks/${id}`);aiProgress.value=`${label}：${task.status==='IN_PROGRESS'?`生成中 ${task.progress||0}%`:task.status}`;if(task.status==='SUCCEEDED')return task;if(task.status==='FAILED'||task.status==='CANCELED')throw Error(task.task_error?.message||'Meshy 生成失败');await new Promise(resolve=>setTimeout(resolve,4000))}throw Error('生成等待超时，可稍后重新打开生成窗口检查')}
async function generateAi(){if(!aiEnabled){ElMessage.info(aiDisabledMessage);return}if(!aiPrompt.value.trim()){ElMessage.warning('先写下想生成的设备外形和结构');return}aiBusy.value=true;aiPreviewStudio?.dispose();aiPreviewStudio=null;generatedAsset.value=null;aiProgress.value='正在生成';generatedPrompt.value=aiPrompt.value.trim()
 try{let asset
  if(aiType.value==='2d'){
    const result=await apiJson('/api/ai/svg',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({prompt:generatedPrompt.value,feedback:aiFeedback.value,previousSvg:aiFeedback.value.trim()?generatedSvg.value:'',provider:svgProvider.value,model:svgProvider.value==='anthropic'?anthropicModel.value:openAiModel.value,baseUrl:anthropicBaseUrl.value})});generatedSvg.value=result.svg
   asset={id:MathUtils.generateUUID(),name:`AI二维设备-${new Date().toLocaleString('zh-CN',{hour12:false})}`,category:category.value,units:'m',ext:'svg',svg:result.svg,generatedByAI:true,prompt:generatedPrompt.value}
  }else{
   const task=await apiJson('/api/ai/3d/tasks',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({prompt:[generatedPrompt.value,aiFeedback.value&&`修改要求：${aiFeedback.value}`].filter(Boolean).join('；'),model:meshyModel.value})});const preview=await waitMeshy(task.result,'形体预览');aiProgress.value='正在生成材质';const refined=await apiJson(`/api/ai/3d/tasks/${preview.id}/refine`,{method:'POST'});await waitMeshy(refined.result,'材质处理');aiProgress.value='正在下载 GLB';const file=await fetch(`/api/ai/3d/tasks/${refined.result}/model`,{headers:aiHeaders()});if(!file.ok)throw Error('下载 GLB 模型失败');asset={id:MathUtils.generateUUID(),name:`AI三维设备-${new Date().toLocaleString('zh-CN',{hour12:false})}`,category:category.value,units:'m',ext:'glb',buffer:await file.arrayBuffer(),generatedByAI:true,prompt:generatedPrompt.value}
  }
  const preview=await assetModel(asset);preview.traverse(o=>{o.geometry?.dispose();const mats=Array.isArray(o.material)?o.material:[o.material];mats.forEach(m=>{if(m){Object.values(m).filter(v=>v?.isTexture).forEach(t=>t.dispose());m.dispose()}})});generatedAsset.value=asset;aiProgress.value='模型已生成，请检查预览；确认后导入设备库';if(asset.ext==='glb'){await nextTick();aiPreviewStudio=createStudio(aiPreviewHost.value,()=>{},()=>{});await aiPreviewStudio.add(asset);aiPreviewStudio.frameAll()}
 }catch(e){ElMessage.error(e.message);aiProgress.value='生成未完成'}finally{aiBusy.value=false}}
async function importGenerated(){if(!generatedAsset.value)return;const asset=generatedAsset.value;try{if(db)await dbCall(db,'put',asset);assets.value.push(asset);filter.value=asset.category;generatedAsset.value=null;aiFeedback.value='';planning.value=false;aiOpen.value=false;const placed=await studio.add(asset);if(placed)studio.focus(placed.id);ElMessage.success('已导入设备库并放入三维场景，可继续检查或编辑')}catch(e){ElMessage.error('导入模型失败：'+e.message)}}
function edit(kind,index,value){if(!selection.value)return;const data=[...selection.value[kind]];data[index]=Number(value)|| (kind==='scale'?1:0);if(kind==='scale')data[index]=Math.max(.01,data[index]);studio.update(selection.value.id,{[kind]:data})}
function exportLayout(){const data={version:1,units:'m',assets:assets.value.map(({buffer,...meta})=>meta),placements:studio.list(),note:'布局 JSON 不包含导入模型二进制文件，请另行保留源模型。模型本地保存在当前浏览器。'};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='warehouse-layout.json';a.click();URL.revokeObjectURL(url)}
onMounted(async()=>{loadAiSettings();refreshAiStatus();try{studio=createStudio(host.value,v=>selection.value=v,saveLayout);try{db=await modelDB();const loaded=await dbCall(db,'getAll');if(!alive){db.close();return}assets.value.push(...loaded)}catch{ElMessage.warning('当前浏览器不能保存模型，导入模型仅在本次会话可用')}
 let saved=[];try{saved=JSON.parse(localStorage.getItem('warehouse-studio-layout-v1')||'[]')}catch{}let missing=0
 for(const p of Array.isArray(saved)?saved:[]){if(!alive)return;const a=assets.value.find(a=>a.id===p.assetId);if(a&&Array.isArray(p.position)&&p.position.length===3){try{await studio.add(a,p)}catch{missing++}}else missing++}
 if(missing)ElMessage.warning(missing+' 个模型未能恢复，请重新导入源模型');restoring=false;ready.value=true;placements.value=studio.list()
 }catch(e){ElMessage.error('编辑器启动失败：'+e.message)}})
onBeforeUnmount(()=>{alive=false;studio?.dispose();aiPreviewStudio?.dispose();db?.close()})
</script>
<template>
 <div class="model-studio" role="dialog" aria-label="设备模型编辑器">
  <header class="studio-header"><div><span class="eyebrow">WAREHOUSE MODEL STUDIO</span><h2>设备模型库与场景布置</h2></div><div><el-button :disabled="!ready" @click="exportLayout">导出布局</el-button><el-button type="primary" @click="emit('close')">返回看板</el-button></div></header>
  <div class="studio-body"><aside class="studio-library"><h3>分类设备库 <span>{{assets.length}}</span></h3><p>按设备分类管理，将模型拖入画布；触屏可点击「放置」。</p><el-input v-model="search" clearable placeholder="搜索设备名称或结构" aria-label="搜索设备模型" style="margin-bottom:10px"/><el-select v-model="filter" aria-label="筛选设备分类"><el-option label="全部设备" value="all"/><el-option v-for="[id,name] in categories" :key="id" :label="name" :value="id"/></el-select><div class="asset-list"><article v-for="a in filtered" :key="a.id" class="asset-card" draggable="true" @dragstart="drag(a,$event)"><div class="asset-symbol">{{equipmentIcons[a.category]||'◇'}}</div><div><b>{{a.name}}</b><small>{{label(a.category)}} · {{a.builtin?'内置':a.ext.toUpperCase()}} · {{a.units}}</small><small v-if="a.spec" class="asset-spec">{{a.spec}}</small><small v-if="a.description">{{a.description}}</small></div><el-button size="small" :disabled="!ready" @click="place(a)">放置</el-button></article></div><section class="studio-import"><h3>导入设备模型</h3><label>设备分类</label><el-select v-model="category" aria-label="导入设备分类"><el-option v-for="[id,name] in categories" :key="id" :label="name" :value="id"/></el-select><label>模型单位</label><el-select v-model="units" aria-label="模型单位"><el-option label="自动：GLB / glTF 米，STL / OBJ 毫米" value="auto"/><el-option label="毫米 mm" value="mm"/><el-option label="米 m" value="m"/></el-select><input ref="fileInput" type="file" accept=".glb,.gltf,.stl,.obj,.sldprt,.sldasm,.step,.stp" hidden @change="importModel"><el-button type="primary" :loading="busy" :disabled="!ready" @click="fileInput.click()">选择模型文件</el-button><p>SolidWorks：另存为 STL（网格），或将装配体转换为 GLB。GLB 保留材质与层级；STL 仅保留几何。OBJ 不加载外部 MTL。原生 CAD 文件需先转换，单文件 ≤30 MB。</p></section></aside>
  <section class="studio-workspace"><nav><el-button :type="planning?'primary':'default'" :disabled="!ready" @click="planning=true">二维规划</el-button><el-button type="primary" :disabled="!ready" @click="generate3D">生成三维</el-button><el-button type="success" :disabled="!ready||!aiEnabled" @click="aiOpen=true;refreshAiStatus()">AI 文字生成模型</el-button><el-radio-group v-model="mode" @change="v=>studio?.mode(v)" size="small"><el-radio-button value="translate">移动</el-radio-button><el-radio-button value="rotate">旋转</el-radio-button><el-radio-button value="scale">缩放</el-radio-button></el-radio-group><el-switch v-model="snap" active-text="0.5 m 网格吸附" @change="v=>studio?.snap(v)"/><span>{{placements.length}} 台设备</span><p v-if="!aiEnabled" class="ai-deployment-note" role="status">{{aiDisabledMessage}}</p></nav><PlanCanvas v-if="planning" :placements="placements" :assets="assets" :selected="selection?.id" :snap="snap" @select="id=>studio.select(id)" @move="movePlan" @drop="dropPlan"/><div v-show="!planning" ref="host" class="studio-canvas" @dragover.prevent @drop.prevent="drop"></div><div class="studio-hint">{{planning?'平面 X/Z 坐标与三维共用 · 左侧设备拖入画布 · 右侧修改尺寸及朝向':'拖拽设备到网格 · 点击选择 · 坐标轴编辑 · 滚轮缩放'}}</div></section>
  <aside class="studio-properties"><h3>场景设备</h3><el-empty v-if="!placements.length" description="从左侧放置第一台设备" :image-size="60"/><button v-for="p in placements" :key="p.id" class="placed-item" :class="{active:selection?.id===p.id}" @click="studio.select(p.id)">{{p.name}}<small>{{label(assets.find(a=>a.id===p.assetId)?.category)}}</small></button><section v-if="selection" class="property-editor"><h3>变换属性</h3><div v-for="[key,name] in [['position','位置 / m'],['rotation','旋转 / rad'],['scale','缩放倍率']]" :key="key"><label>{{name}}</label><div v-for="(axis,i) in ['X','Y','Z']" :key="axis" class="axis-editor"><span>{{axis}}</span><el-input-number :model-value="selection[key][i]" :min="key==='scale'?.01:undefined" :step="key==='rotation'?.1:.5" :precision="2" @change="v=>edit(key,i,v)"/></div></div><el-button @click="studio.focus(selection.id)">聚焦模型</el-button><el-button type="danger" @click="studio.remove(selection.id)">删除实例</el-button></section><p class="studio-note">模型和布局保存在当前浏览器。布置的导入模型为静态展示，不自动绑定仿真或真实设备报警。</p></aside></div>
  <el-dialog v-model="aiOpen" title="AI 设备模型生成" width="min(680px, 94vw)" append-to-body>
   <div class="ai-generator">
    <p v-if="!aiEnabled">{{aiDisabledMessage}}</p>
    <p v-else>描述设备结构、视角和细节，生成后可预览并导入设备库；觉得不合适，写修改意见后再次生成。</p>
    <div class="ai-provider-status"><span :class="(svgProvider==='anthropic'?aiReady.anthropic:aiReady.openai)?'ok':''">二维生成：{{(svgProvider==='anthropic'?aiReady.anthropic:aiReady.openai)?(svgProvider==='anthropic'?'Claude 兼容服务已连接':'OpenAI 已连接'):'未配置 Token'}}</span><span :class="aiReady.meshy?'ok':''">三维生成：{{aiReady.meshy?'Meshy 已连接':'未配置 Token'}}</span><el-button link type="primary" :disabled="!aiEnabled" @click="aiSettingsOpen=!aiSettingsOpen">{{aiSettingsOpen?'收起 Token 配置':'配置 API Token'}}</el-button></div>
    <div v-if="aiEnabled&&aiSettingsOpen" class="ai-settings-panel">
     <label>二维生成服务</label><el-select v-model="svgProvider"><el-option label="APIKEY.FUN / Claude 兼容接口" value="anthropic"/><el-option label="OpenAI 官方 Responses API" value="openai"/></el-select>
     <template v-if="svgProvider==='anthropic'"><label>服务商 API Key（Claude 兼容）</label><el-input v-model="anthropicToken" type="password" show-password autocomplete="off" placeholder="在 APIKEY.FUN 控制台创建并粘贴 API Key"/><label>请求地址</label><el-input v-model="anthropicBaseUrl" placeholder="https://api.apikey.fun"/><small class="ai-provider-hint">填写兼容 Claude API 的服务端点，不要以斜杠结尾；默认按 /v1/messages 调用。</small><label>模型名称</label><el-input v-model="anthropicModel" placeholder="填写服务商控制台提供的 Claude 模型名"/></template>
     <template v-else><label>OpenAI API Key（二维 SVG）</label><el-input v-model="openAiToken" type="password" show-password autocomplete="off" placeholder="粘贴 OpenAI API Key；留空时保留服务端配置"/><label>二维模型</label><el-input v-model="openAiModel" placeholder="gpt-4.1-mini"/></template>
     <label>Meshy API Key（三维 GLB）</label><el-input v-model="meshyToken" type="password" show-password autocomplete="off" placeholder="粘贴 Meshy API Key；留空时保留服务端配置"/>
     <label>三维模型</label><el-select v-model="meshyModel"><el-option label="Meshy T2.5 · 成本较低，拓扑适合编辑" value="meshy-t2.5"/><el-option label="Meshy 7.1 · 细节优先" value="meshy-7.1"/></el-select>
     <div class="ai-settings-actions"><el-button type="primary" @click="saveAiSettings">保存到当前标签页</el-button><el-button @click="clearAiSettings">清除此标签页 Token</el-button></div>
     <small>Token 只存于当前浏览器标签页会话，并通过本机代理转发给服务商；关闭标签页会清除。不要在共享电脑或公开部署环境输入密钥。</small>
    </div>
    <el-radio-group v-model="aiType" :disabled="aiBusy"><el-radio-button value="2d">二维 SVG 图标</el-radio-button><el-radio-button value="3d">三维 GLB 模型</el-radio-button></el-radio-group>
    <label>设备分类</label><el-select v-model="category"><el-option v-for="[id,name] in categories" :key="id" :label="name" :value="id"/></el-select>
    <label>生成描述</label><el-input v-model="aiPrompt" type="textarea" :rows="4" maxlength="800" show-word-limit placeholder="例如：俯视图的双立柱堆垛机，橙色钢结构，中央提升货叉，轮廓清晰，便于仓库平面图辨认"/>
    <label>修改意见（可选）</label><el-input v-model="aiFeedback" type="textarea" :rows="2" maxlength="1000" placeholder="例如：底座再窄一些，增加两侧导轨，保留俯视轮廓"/>
    <div v-if="generatedAsset?.ext==='svg'" class="ai-svg-preview"><img :src="svgPreviewUrl(generatedSvg)" alt="AI 生成的二维设备 SVG 预览"/><span>二维图形预览</span></div>
    <div v-if="generatedAsset?.ext==='glb'" ref="aiPreviewHost" class="ai-model-preview" aria-label="三维 GLB 模型预览"/>
    <p v-if="aiProgress" class="ai-progress">{{aiProgress}}</p>
    <p class="ai-cost-note">推荐 Meshy T2.5 生成三维结构示意，成本低且拓扑较规整；也可切换 Meshy 7.1 优先细节。当前价表中 T2.5 为预览 5 + 2K 材质 10 credits，7.1 为预览 20 + 材质 10 credits；以服务商账户页面为准。二维可通过 APIKEY.FUN Claude 兼容接口或 OpenAI 生成 SVG。输出是数字孪生可视模型，请校核尺寸和工程结构。</p>
   </div>
   <template #footer><el-button @click="aiOpen=false">关闭</el-button><el-button type="primary" :loading="aiBusy" :disabled="!aiEnabled" @click="generateAi">{{generatedAsset?'重新生成 / 按意见修改':'生成预览'}}</el-button><el-button type="success" :disabled="!aiEnabled||!generatedAsset||aiBusy" @click="importGenerated">导入设备库</el-button></template>
  </el-dialog>
 </div>
</template>
